79: // ---------- deploy review output ----------
80: 
81: const reviewFmt = {
82:   findings: (x) => `[${x.severity}] ${x.at} — ${x.text}`,
83:   secrets: (x) => `${x.name} ${x.declared ? 'declared' : 'NOT DECLARED'} · used at ${x.used_at}`,
84:   undeclared_secrets: (x) => x,
85:   outbound: (x) => `${x.host} — ${x.purpose} (${x.at})`,
86:   aws: (x) => `${x.action} ${x.resource} (${x.at})`,
87:   shell_exec: (x) => `${x.at} — ${x.command}${x.user_input_reaches_it ? ' · user input reaches it' : ''}`,
88: };
89: 
90: function reviewLine(r) {
91:   const aws = (r.aws || []).length;
92:   const lambdas = (r.aws || []).filter((a) => (a.action || '').startsWith('lambda:')).length;
93:   const awsPart = !aws ? 'no AWS' : lambdas === aws ? `invokes ${aws} Lambda${aws > 1 ? 's' : ''}` : `${aws} AWS call${aws > 1 ? 's' : ''}`;
94:   const hosts = new Set((r.outbound || []).map((o) => o.host)).size;
95:   const outPart = !hosts ? 'no outbound' : `${hosts} outbound host${hosts > 1 ? 's' : ''}`;
96:   const shell = (r.shell_exec || []).length;
97:   const shellPart = !shell ? 'no shell exec' : `${shell} shell exec`;
98:   return `review: ${awsPart} · ${outPart} · ${shellPart} · ${r.risk}`;
99: }
100: 
101: function printReport(res) {
102:   const r = res.review;
103:   const section = (title, key) => {
104:     if (!(r[key] || []).length) return;
105:     console.log(`${title}:`);
106:     for (const x of r[key]) console.log(`  ${reviewFmt[key](x)}`);
107:   };
108:   section('findings', 'findings');
109:   section('secrets', 'secrets');
110:   section('undeclared secrets', 'undeclared_secrets');
111:   section('outbound', 'outbound');
112:   section('aws', 'aws');
113:   section('shell exec', 'shell_exec');
114:   const fsys = r.filesystem || { reads: [], writes: [] };
115:   console.log('filesystem:');
116:   console.log(`  reads: ${fsys.reads.join(', ') || '—'}`);
117:   console.log(`  writes: ${fsys.writes.join(', ') || '—'}`);
118:   if ((r.skipped || []).length) console.log(`skipped: ${r.skipped.join(', ')}`);
119:   console.log(`summary: ${r.summary}`);
120:   console.log(`risk: ${r.risk} (${res.model || 'unknown model'}, ${res.reviewedAt})`);
121: }
122: 
123: function printDiff(res) {
124:   if (!res.prev) return console.log('no previous review to diff against');
125:   const { prev, review: cur } = res;
126:   let changed = false;
127:   if (prev.risk !== cur.risk) {
128:     console.log(`risk: ${prev.risk} → ${cur.risk}`);
129:     changed = true;
130:   }
131:   for (const key of Object.keys(reviewFmt)) {
132:     const before = new Set((prev[key] || []).map(reviewFmt[key]));
133:     const after = new Set((cur[key] || []).map(reviewFmt[key]));
134:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ ${key.replace('_', ' ')}: ${s}`);
135:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- ${key.replace('_', ' ')}: ${s}`);
136:   }
137:   for (const dir of ['reads', 'writes']) {
138:     const before = new Set((prev.filesystem || {})[dir] || []);
139:     const after = new Set((cur.filesystem || {})[dir] || []);
140:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ filesystem ${dir}: ${s}`);
141:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- filesystem ${dir}: ${s}`);
142:   }
143:   if (!changed) console.log('no changes since previous deploy');
144: }
