146: const commands = {
147:   async login() {
148:     if (flags.api) config.save({ ...config.load(), apiBase: flags.api });
149:     const email = flags.email || (await ask('work email: '));
150:     const res = await call('POST', '/api/cli/login', { email }, { auth: false });
151:     if (res.devCode) console.log(`(dev) code: ${res.devCode}`);
152:     else console.log(`✓ code sent to ${email}`);
153:     const code = flags.code || (await ask('6-digit code: '));
154:     const v = await call('POST', '/api/cli/verify', { challenge: res.challenge, code }, { auth: false });
155:     config.save({ ...config.load(), token: v.token, email: v.email, org: v.org, apiBase: apiBase() });
156:     console.log(`✓ logged in as ${v.email} (org: ${v.org})`);
157:   },
158: 
159:   async init() {
160:     const dir = process.cwd();
161:     if (!init(dir, { force: !!flags.force })) {
162:       process.exitCode = 1;
163:       return;
164:     }
165:     // First runbook, from the code as it stands. Never fails the init.
166:     const rbPath = path.join(dir, 'RUNBOOK.md');
167:     if (fs.existsSync(rbPath) && !flags.force) return console.log('RUNBOOK.md already exists — use --force to regenerate');
168:     try {
169:       const app = detect(dir);
170:       const { bundle } = buildBundle(dir, app.entry, envfile.parse(path.join(dir, '.env')));
171:       const { runbook } = await call('POST', '/api/runbook', { bundle });
172:       fs.writeFileSync(rbPath, runbook);
173:       console.log('✓ wrote RUNBOOK.md');
174:     } catch (e) {
175:       console.log(`runbook: unavailable (${e.message}) — regenerated on every small deploy`);
176:     }
177:   },
178: 
179:   async deploy() {
180:     const dir = process.cwd();
181:     if (!fs.existsSync(path.join(dir, 'small.toml')) && !init(dir)) {
182:       process.exitCode = 1;
183:       return;
184:     }
185:     const app = detect(dir, flags);
186:     console.log(`✓ entry: ${app.entry} (${app.framework}) via ${app.via}`);
187:     inputs.checkSchema(app.config); // bad [inputs]/[outputs] stops the deploy here
188: 
189:     const src = source.capture(dir);
190:     if (src) {
191:       const repo = src.repoUrl ? `${src.repoUrl.replace(/^https:\/\//, '')} @ ` : '';
192:       console.log(`✓ source: ${repo}${src.branch} ${src.shortCommit}`);
193:       if (src.dirty) console.log('⚠ uncommitted changes deployed — commit before sharing');
194:     } else {
195:       console.log('source: not a git repo');
196:     }
197: 
198:     const envPath = path.resolve(dir, typeof flags.env === 'string' ? flags.env : '.env');
199:     const secrets = envfile.parse(envPath);
200:     const required = (app.config.secrets && app.config.secrets.required) || [];
201:     const missing = required.filter((k) => !(k in secrets));
202:     if (missing.length) throw new Error(`missing secrets: ${missing.join(', ')} — add them to ${envPath}`);
203: 
204:     write(dir, app);
205:     const review = buildBundle(dir, app.entry, secrets);
206:     const visibility = (app.config.access && app.config.access.visibility) || undefined;
207:     const storage = app.config.storage;
208:     let sizeGb;
209:     if (storage) {
210:       const m = /^(\d+)\s*gb$/i.exec(String(storage.size || '1GB'));
211:       if (!m) throw new Error('storage.size must be whole gigabytes, like "1GB"');
212:       sizeGb = Number(m[1]);
213:     }
214:     const awsRoleArn = (app.config.aws && app.config.aws.role_arn) || undefined;
215:     const kind = app.config.kind === 'job' ? 'job' : 'server';
216:     const schedule = app.config.schedule;
217:     const d = await call('POST', '/api/deploy', {
218:       name: app.name,
219:       framework: app.framework,
220:       visibility,
221:       awsRoleArn,
222:       kind,
223:       storage: storage ? { sizeGb } : undefined,
224:       schedule: kind === 'job' ? schedule || null : undefined, // null clears a removed schedule
225:       source: src ? { repoUrl: src.repoUrl, branch: src.branch, commit: src.commit, dirty: src.dirty } : undefined,
226:     });
227:     if (!d.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
228:     if (storage && !d.volumeRegion) throw new Error('control plane does not support [storage] yet — redeploy the worker');
229:     writeFlyToml(dir, d.flyApp, app.config.memory, storage ? { path: storage.path || '/data', region: d.volumeRegion } : undefined);
230:     if (storage) console.log(`✓ storage: ${storage.path || '/data'} (${sizeGb}GB volume in ${d.volumeRegion}, survives redeploys)`);
231: 
232:     // The worker's waitUntil window (~30s) is too short for the model to write review +
233:     // runbook, so the CLI holds this request open in parallel with the Fly build instead;
234:     // the worker awaits the model and stores the result before responding.
235:     const reviewPromise = call('POST', '/api/review/run', {
236:       app: app.name,
237:       bundle: review.bundle,
238:       skipped: review.skipped,
239:     }).catch(() => null);
240:     const printReview = async () => {
241:       const res = await reviewPromise;
242:       if (res && res.review) console.log(reviewLine(res.review));
243:       else console.log('review: unavailable');
244:     };
245: 
246:     if (kind === 'job') {
247:       if (schedule) {
248:         if (!d.nextRun && !d.schedulePaused) throw new Error('control plane does not support schedule yet — redeploy the worker');
249:         const next = d.schedulePaused
250:           ? `paused — small schedule resume ${app.name}`
251:           : `next run ${new Date(d.nextRun).toISOString().slice(0, 16).replace('T', ' ')}`;
252:         console.log(`✓ schedule: ${schedule} (UTC) · ${next}`);
253:       }
254:       // jobs: build + register the image, start nothing — the control plane starts machines per run
255:       fly.setSecrets(d.flyApp, d.flyToken, secrets);
256:       const image = fly.buildImage(d.flyApp, d.flyToken, dir, `v${Date.now()}`);
257:       await call('POST', '/api/image', { app: app.name, image });
258:       console.log(`✓ built ${app.name} — start it with: small run ${app.name}`);
259:       await printReview();
260:       return;
261:     }
262: 
263:     // gradio builds asset/API URLs from its root; behind the path proxy that must be the public URL
264:     const rootPath = app.framework === 'gradio' ? { GRADIO_ROOT_PATH: d.url.replace(/\/$/, '') } : {};
265:     // [aws] role: guard fetches STS session creds from the control plane at boot
266:     const cpUrl = awsRoleArn ? { SMALL_CP_URL: apiBase() } : {};
267:     // guard batches request-log lines here, authed by the proxy secret it already holds
268:     const logUrl = { SMALL_LOG_URL: `${apiBase()}/api/apps/${app.name}/request-log` };
269:     fly.setSecrets(d.flyApp, d.flyToken, { SMALL_PROXY_SECRET: d.proxySecret, ...rootPath, ...cpUrl, ...logUrl, ...secrets });
270:     if (awsRoleArn) console.log(`✓ aws role: ${awsRoleArn} (STS via control plane)`);
271:     fly.deploy(d.flyApp, d.flyToken, dir);
272: 
273:     console.log(`✓ deployed → ${d.url}`);
274:     const { org } = config.load();
275:     console.log(visibility === 'private' ? '✓ login required · explicit members only' : `✓ login required · anyone @${org}`);
276:     await printReview();
277:   },
278: 
279:   async review() {
280:     const name = flags._[0] || appName(process.cwd());
281:     const res = await call('GET', `/api/review?app=${encodeURIComponent(name)}`);
282:     if (!res.review) return console.log('review: unavailable — no reviewed deploy yet');
283:     if (flags.diff) printDiff(res);
284:     else printReport(res);
285:   },
286: 
287:   async runbook() {
288:     const name = flags._[0] || appName(process.cwd());
289:     const res = await call('GET', `/api/review?app=${encodeURIComponent(name)}`);
290:     const cur = res.review && res.review.runbook;
291:     if (!cur) return console.log('runbook: unavailable — no reviewed deploy yet');
292:     if (flags.diff) {
293:       const prev = res.prev && res.prev.runbook;
294:       if (!prev) return console.log('no previous runbook to diff against');
295:       // ponytail: line-set diff, no ordering — mirror of review --diff; real diff when it matters
296:       const before = new Set(prev.split('\n'));
297:       const after = new Set(cur.split('\n'));
298:       let changed = false;
299:       for (const l of cur.split('\n')) if (!before.has(l)) (changed = true), console.log(`+ ${l}`);
300:       for (const l of prev.split('\n')) if (!after.has(l)) (changed = true), console.log(`- ${l}`);
301:       if (!changed) console.log('no changes since previous deploy');
302:       return;
303:     }
304:     if (flags.write) {
305:       fs.writeFileSync(path.join(process.cwd(), 'RUNBOOK.md'), cur);
306:       return console.log('✓ wrote RUNBOOK.md');
307:     }
308:     console.log(cur);
309:   },
310: 
311:   async run() {
312:     const name = flags._[0] || appName(process.cwd());
313:     if (flags.download) return downloadOutputs(name, typeof flags.download === 'string' ? flags.download : '.');
314: 
315:     const cfg = localConfig(name);
316:     if (cfg) inputs.checkSchema(cfg);
317:     const extra = Object.keys(flags).filter((k) => !['_', 'app'].includes(k));
318:     if (!cfg && extra.length) throw new Error(`--${extra[0]}: no small.toml for ${name} here — run from the app directory to pass inputs`);
319:     const { values, files } = cfg ? inputs.validate(cfg.inputs, flags) : { values: {}, files: {} };
320: 
321:     if (Object.keys(values).length) {
322:       const line = Object.entries(values)
323:         .map(([k, v]) => (files[k] ? `${k}=${v} (${fmtSize(files[k].size)})` : `${k}=${v}`))
324:         .join(' · ');
325:       console.log(`✓ inputs: ${line}`);
326:     }
327:     const total = Object.values(files).reduce((s, f) => s + f.size, 0);
328:     if (total > 100 * 1024 * 1024) throw new Error(`input files total ${fmtSize(total)} — cap is 100 MB per run`);
329: 
330:     let body;
331:     if (Object.keys(files).length) {
332:       // files ride a multipart POST; scalars stay in the JSON part
333:       body = new FormData();
334:       body.append('body', JSON.stringify({ app: name, inputs: values }));
335:       for (const [n, f] of Object.entries(files)) body.append(`input:${n}`, new Blob([fs.readFileSync(f.path)]), path.basename(f.path));
336:     } else {
337:       body = { app: name, inputs: Object.keys(values).length ? values : undefined };
338:     }
339:     const { runId } = await call('POST', '/api/runs', body);
340:     console.log(`run: ${runId}`);
341:     let cursor = -1;
342:     for (;;) {
343:       const r = await call('GET', `/api/runs/${encodeURIComponent(runId)}?after=${cursor}`);
344:       for (const line of r.lines) console.log(line);
345:       if (r.lines.length) cursor = r.cursor;
346:       if (r.status !== 'running' && !r.lines.length) {
347:         console.log(r.exitCode === 0 ? `✓ finished (exit ${r.exitCode})` : `✗ failed (exit ${r.exitCode})`);
348:         await printOutputs(name, runId);
349:         process.exitCode = r.exitCode === 0 ? 0 : 1;
350:         return;
351:       }
352:       await new Promise((res) => setTimeout(res, 1000));
353:     }
354:   },
355: 
356:   async runs() {
357:     const name = flags._[0] || appName(process.cwd());
358:     const { runs } = await call('GET', `/api/runs?app=${encodeURIComponent(name)}`);
359:     if (!runs.length) return console.log(`no runs yet — small run ${name}`);
