11:     if (!TYPES.includes(spec.type)) throw new Error(`[inputs] ${name}: unknown type "${spec.type}" — one of ${TYPES.join(', ')}`);
12:     if (spec.type === 'select' && !Array.isArray(spec.options)) throw new Error(`[inputs] ${name}: select needs options = ["a", "b"]`);
13:   }
14:   for (const [name, spec] of Object.entries(config.outputs || {})) {
15:     if (!spec || typeof spec !== 'object' || typeof spec.path !== 'string') throw new Error(`[outputs] ${name} needs path = "file.ext"`);
16:   }
17: }
