19: // "-7d" and friends resolve to a concrete date here so the script gets YYYY-MM-DD.
20: function resolveDate(raw, flag) {
21:   const s = String(raw);
22:   if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
23:   const rel = s.match(/^-(\d+)d$/);
24:   if (rel) return new Date(Date.now() - Number(rel[1]) * 86400000).toISOString().slice(0, 10);
25:   throw new Error(`--${flag} must be YYYY-MM-DD or -<n>d, got "${s}"`);
